func newline_init(tls *libc.TLS, env uintptr) (r uint8) {
	return libc.BoolUint8((*State)(unsafe.Pointer((*Env)(unsafe.Pointer(env)).Fstate)).Fnewline.Fstate == int32(NInit))
}

